// Brand marks for the /links page, inlined as SVG so the page makes no external
// requests and the logos stay crisp at any size.
//
// Sources: simple-icons (CC0) for the brand marks, bootstrap-icons (MIT) for
// LinkedIn and the envelope — simple-icons dropped LinkedIn over a trademark
// request. Paths are verbatim; only the wrapper is ours.
//
// `light`/`dark` are the colours the mark is drawn in per theme. Brand black
// reads as a smudge on the dark surface, so GitHub and Letterboxd flip to the
// theme text colour instead.

export type BrandIconId =
    | "github"
    | "linkedin"
    | "instagram"
    | "facebook"
    | "letterboxd"
    | "spotify"
    | "email"
    | "rust"

type BrandIcon = {
    title: string
    viewBox: string
    paths: string[]
    light: string
    dark: string
}

