export function BrandLogo({ id, className = "brand-logo" }: { id: BrandIconId; className?: string }) {
    const icon = brandIcons[id]

    return (
        <svg
            className={className}
            viewBox={icon.viewBox}
            fill="currentColor"
            role="img"
            aria-hidden="true"
            focusable="false"
        >
            {icon.paths.map(d => (
                <path key={d} d={d} />
            ))}
        </svg>
    )
}
